use calibration_liveview::CalibrationOffset;
use crate::timing::{TimingMode,TimingRoute,TimingRate};

#[derive(Clone,Copy)]
pub(crate) struct CalibrationPair { pub high:CalibrationOffset, pub low:CalibrationOffset }
#[derive(Clone,Copy)]
pub(crate) struct IntervalKeys { pub first:CalibrationPair, pub second:CalibrationPair }
#[derive(Clone,Copy)]
pub(crate) struct PulseKeys { pub first_flag:CalibrationOffset, pub second_flag:CalibrationOffset, pub first:CalibrationPair, pub second:CalibrationPair }
#[derive(Clone,Copy)]
pub(crate) struct OutputKeys { pub interval:CalibrationPair, pub enabled:CalibrationOffset }
#[derive(Clone,Copy)]
pub(crate) struct DirectControlKeys { pub flags:CalibrationOffset, pub clock:CalibrationOffset }
#[derive(Clone,Copy)]
pub(crate) struct AdjustmentKeys { pub interval:CalibrationPair, pub first_flag:CalibrationOffset, pub phase:CalibrationPair, pub second_flag:CalibrationOffset }
#[derive(Clone,Copy)]
pub(crate) struct ModeKeys { pub control:DirectControlKeys, pub dimensions:IntervalKeys, pub pulse:PulseKeys, pub interval:IntervalKeys, pub delay:Option<CalibrationOffset>, pub output:OutputKeys, pub output_interval:IntervalKeys }
#[derive(Clone,Copy)]
pub(crate) struct RouteKeys { pub control:[CalibrationOffset;3], pub dimensions:IntervalKeys, pub pulse:PulseKeys, pub interval:IntervalKeys, pub output:OutputKeys, pub output_interval:IntervalKeys, pub secondary_output:OutputKeys, pub secondary_output_interval:IntervalKeys, pub adjustment:AdjustmentKeys }
const fn key(value:usize)->CalibrationOffset { match CalibrationOffset::parse(value) { Some(key)=>key, None=>panic!("calibration selector outside cache") } }
pub(crate) const CONTROL_ENABLE:CalibrationOffset=key(0x104e);
pub(crate) const DEFAULT_SELECTOR:CalibrationOffset=key(0x1083);
pub(crate) const DEFAULT_INTERVAL:CalibrationPair=CalibrationPair {high:key(0x1081),low:key(0x1082)};
pub(crate) const DEFAULT_FLAG:CalibrationOffset=key(0x1080);

