pub(crate) fn route(route:TimingRoute,rate:TimingRate)->&'static RouteKeys {
    let bank=if route==TimingRoute::Two {2}else{0};
    let speed=if rate.raw()==1 {0}else{1};
    &ROUTES[bank+speed]
}
